const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const ROOT = process.cwd();
const RUN = path.join(ROOT, 'run.js');
const COUNTER = path.join(ROOT, 'counter.json');
const LOG = path.join(ROOT, 'log.txt');

const orig = fs.readFileSync(RUN, 'utf8');
console.log('--- ORIGINAL run.js ---');
console.log(orig);
console.log('--- END ORIGINAL ---');

const fixed = [
"const fs = require('fs');",
"const path = require('path');",
"",
"const DIR = __dirname;",
"const COUNTER = path.join(DIR, 'counter.json');",
"const LOG = path.join(DIR, 'log.txt');",
"const N = Number(process.argv[2] || 0);",
"",
"// reset on start (preserved behavior)",
"fs.writeFileSync(COUNTER, JSON.stringify({ n: 0 }));",
"fs.writeFileSync(LOG, '');",
"",
"// FIX: single-writer queue. Concurrent tasks still start all at once, but every",
"// read-modify-write of counter.json and every log append is serialized, so no",
"// update can be lost by overlapping read/short-write pairs.",
"let tail = Promise.resolve();",
"function enqueue(fn) {",
"  const run = tail.then(fn, fn);",
"  tail = run.then(function () {}, function () {});",
"  return run;",
"}",
"",
"function incrementTask() {",
"  return enqueue(function () {",
"    return fs.promises.readFile(COUNTER, 'utf8').then(function (raw) {",
"      const data = JSON.parse(raw);",
"      data.n += 1;",
"      return fs.promises.writeFile(COUNTER, JSON.stringify(data)).then(function () {",
"        return fs.promises.appendFile(LOG, 'increment ' + data.n + String.fromCharCode(10));",
"      });",
"    });",
"  });",
"}",
"",
"const tasks = [];",
"for (let i = 0; i < N; i++) tasks.push(incrementTask());",
"",
"Promise.all(tasks)",
"  .then(function () { return fs.promises.readFile(COUNTER, 'utf8'); })",
"  .then(function (raw) {",
"    console.log('n=' + JSON.parse(raw).n);",
"  })",
"  .catch(function (e) {",
"    console.error(e && e.stack ? e.stack : e);",
"    process.exit(1);",
"  });",
""
].join('\n');

fs.writeFileSync(RUN, fixed, 'utf8');

let ok = true;
for (const N of [3, 7]) {
  let stdout = '';
  try {
    stdout = execFileSync(process.execPath, [RUN, String(N)], { encoding: 'utf8', cwd: ROOT });
  } catch (e) {
    stdout = String((e && e.stdout) || '') + ' | STDERR: ' + String((e && e.stderr) || '');
    ok = false;
  }
  const counter = JSON.parse(fs.readFileSync(COUNTER, 'utf8'));
  const raw = fs.readFileSync(LOG, 'utf8');
  const lines = raw.split('\n').filter(function (l) { return l.trim() !== ''; }).length;
  const printed = stdout.trim();
  const good = counter.n === N && lines === N && printed === 'n=' + N;
  if (!good) ok = false;
  console.log('RUN N=' + N + ' -> stdout=' + JSON.stringify(printed) +
    ' counter.json=' + JSON.stringify(counter) +
    ' log.txt lines=' + lines +
    ' OK=' + good);
}

if (ok) {
  console.log('DONE: run.js fixed; N=3 and N=7 both give n=N, N log lines, stdout n=N');
} else {
  console.log('NOT DONE: verification failed');
}

