const fs = require('fs');
const vm = require('vm');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Auto-rotating cube - three.js</title>
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#0b0f19}
  canvas{display:block}
</style>
</head>
<body>
<script src="https://cdn.jsdelivr.net/npm/three@0.128.0/build/three.min.js"></script>
<script>
(function () {
  var state = { error: null, frames: 0, rafScheduled: false, last: 0, rotY: 0 };
  var scene, camera, renderer, cube;

  function init() {
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 0, 3);

    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(window.devicePixelRatio || 1);
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    cube = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({ color: 0x4ea1ff, roughness: 0.35, metalness: 0.1 })
    );
    scene.add(cube);

    scene.add(new THREE.AmbientLight(0xffffff, 0.6));
    var dir = new THREE.DirectionalLight(0xffffff, 0.9);
    dir.position.set(2, 3, 4);
    scene.add(dir);

    window.addEventListener('resize', function () {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    requestAnimationFrame(loop);
  }

  function step(t) {
    if (!state.last) state.last = t;
    var dt = Math.min((t - state.last) / 1000, 0.1);
    state.last = t;
    state.rotY += dt * 1.0;
    cube.rotation.y = state.rotY;
    cube.rotation.x = state.rotY * 0.45;
    renderer.render(scene, camera);
    state.frames++;
  }

  function loop(t) {
    step(t);
    state.rafScheduled = true;
    requestAnimationFrame(loop);
  }

  window.__selfcheck = function () {
    var checks = [];
    function push(name, pass, evidence) {
      checks.push({ name: name, pass: !!pass, evidence: String(evidence) });
    }

    var s = document.querySelector('script[src*="three"]');
    push('three.js loaded from CDN',
      typeof THREE !== 'undefined' && !!THREE.REVISION,
      'script[src*="three"] -> ' + (s ? s.src : 'missing') + ' ; THREE.REVISION=' +
        (typeof THREE !== 'undefined' ? THREE.REVISION : 'undefined'));

    push('no init error', !state.error, 'state.error=' + state.error);

    push('renderer canvas mounted',
      !!(renderer && renderer.domElement && document.body.contains(renderer.domElement)),
      renderer && renderer.domElement ? renderer.domElement.tagName + ' appended to document.body' : 'no renderer');

    push('cube mesh added to scene',
      !!(cube && scene && scene.children.indexOf(cube) !== -1),
      cube ? cube.geometry.type + ' at scene.children[' + scene.children.indexOf(cube) + ']' : 'no cube');

    push('requestAnimationFrame loop active',
      state.rafScheduled && state.frames > 0,
      'frames=' + state.frames + ' rafScheduled=' + state.rafScheduled);

    var before = cube ? cube.rotation.y : 0;
    var after = before;
    try {
      step(state.last + 250);
      after = cube.rotation.y;
    } catch (e) {
      state.error = 'rotation probe failed: ' + (e && e.message);
    }
    push('cube auto-rotates', after > before,
      'rotation.y ' + before.toFixed(4) + ' -> ' + after.toFixed(4));

    var pass = checks.every(function (c) { return c.pass; });
    return { checks: checks, pass: pass };
  };

  try { init(); } catch (e) { state.error = e && e.message; console.error(e); }
})();
</script>
</body>
</html>
`;

fs.writeFileSync('index.html', html, 'utf8');
const src = fs.readFileSync('index.html', 'utf8');

const staticOk = /<script src="https:\/\/cdn\.jsdelivr\.net\/npm\/three@[\d.]+\/build\/three\.min\.js"><\/script>/.test(src);

// ---- run the inline script inside a mocked DOM/THREE ----
const queue = [];
const bodyChildren = [];
function mkEl(tag) {
  return { tagName: tag.toUpperCase(), style: {}, width: 0, height: 0, getContext() { return {}; }, addEventListener() {} };
}
const documentMock = {
  body: {
    appendChild(el) { bodyChildren.push(el); },
    contains(el) { return bodyChildren.indexOf(el) !== -1; }
  },
  createElement: mkEl,
  querySelector(sel) {
    return /three/.test(sel) ? { src: 'https://cdn.jsdelivr.net/npm/three@0.128.0/build/three.min.js' } : null;
  },
  addEventListener() {}
};
function Noop() {}
function Scene() { this.children = []; }
Scene.prototype.add = function (o) { this.children.push(o); };
function PerspectiveCamera() {
  const p = { x: 0, y: 0, z: 0 };
  p.set = function (x, y, z) { this.x = x; this.y = y; this.z = z; };
  this.position = p;
  this.aspect = 1;
}
PerspectiveCamera.prototype.updateProjectionMatrix = function () {};
function WebGLRenderer() { this.domElement = mkEl('canvas'); this.renders = 0; }
WebGLRenderer.prototype.setSize = function () {};
WebGLRenderer.prototype.setPixelRatio = function () {};
WebGLRenderer.prototype.render = function () { this.renders++; };
function Mesh(g, m) { this.geometry = g; this.material = m; this.rotation = { x: 0, y: 0, z: 0 }; }
function BoxGeometry() { this.type = 'BoxGeometry'; }
const THREE = {
  REVISION: '128', Scene, PerspectiveCamera, WebGLRenderer, Mesh, BoxGeometry,
  MeshStandardMaterial: Noop, AmbientLight: Noop, DirectionalLight: Noop
};

const sandbox = {
  console, THREE, document: documentMock,
  innerWidth: 800, innerHeight: 600, devicePixelRatio: 1,
  requestAnimationFrame(cb) { queue.push(cb); return queue.length; },
  addEventListener() {},
  performance: { now: () => Date.now() }
};
sandbox.window = sandbox;
sandbox.globalThis = sandbox;
vm.createContext(sandbox);

const code = src.match(/<script>([\s\S]*?)<\/script>/)[1];
vm.runInContext(code, sandbox);

[0, 16, 32].forEach(function (t) { const cb = queue.shift(); if (cb) cb(t); });

const res = sandbox.window.__selfcheck();

console.log('file: index.html (' + Buffer.byteLength(src) + ' bytes)');
console.log('static cdn <script src> tag found: ' + staticOk);
res.checks.forEach(function (c) { console.log('  [' + (c.pass ? 'PASS' : 'FAIL') + '] ' + c.name + ' | ' + c.evidence); });
console.log('window.__selfcheck() => ' + JSON.stringify({ pass: res.pass, checks: res.checks.length }));

const ok = staticOk && res.pass && typeof res.pass === 'boolean' && res.checks.length >= 5;
if (ok) console.log('DONE: pass=true, ' + res.checks.length + ' checks, index.html written and selfcheck executed');
else console.log('FAIL: pass=' + res.pass + ' static=' + staticOk);
process.exit(ok ? 0 : 1);
